cd /private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/uv && python3 - <<'PY'
import pathlib
ROOT = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature')

p = ROOT / 'src/codegen/lower_inst/builtins/io/string_validation.rs'
t = p.read_text()
probe = '''
    eprintln!("PROBE {name}: declared={declared:?} loaded={loaded:?}");'''
assert t.count(probe) == 1
p.write_text(t.replace(probe, ''))
print('probe removed')

p = ROOT / 'src/ir_lower/expr/array_builtin_args.rs'
t = p.read_text()
old = '''        if param.by_ref {
            continue;
        }
        if !matches!(ctx.builder.value_php_type(*value), PhpType::Void) {
            continue;
        }'''
new = '''        if param.by_ref {
            continue;
        }
        // A parameter whose default is `null` is php's `?T $x = null`, and php does NOT coerce an
        // explicit null there — it means "no bound", and the builtin reads it as such. The
        // DECLARED type alone cannot tell the two apart: this contract spells the nullable case as
        // `Int` plus a null default, so reading only `param.ty` turned `stream_get_contents($h,
        // null)` into a request for ZERO bytes (it answered `""`) and
        // `stream_copy_to_stream($a, $b, null)` into a copy of nothing, where `php -n` 8.5.6
        // answers the whole stream for both. The coercion below stays for the parameters php
        // really does coerce — a non-nullable scalar, whose default is never null.
        if matches!(param.default, Some(crate::builtins::spec::DefaultSpec::Null)) {
            continue;
        }
        if !matches!(ctx.builder.value_php_type(*value), PhpType::Void) {
            continue;
        }'''
assert t.count(old) == 1, 'coercion guard not found'
p.write_text(t.replace(old, new))
print('array_builtin_args.rs: a nullable parameter keeps its null')
